26	/**
27	 * This class represents the difference between our replica of a container and a peer's replica of a container.
28	 * It summarizes the operations we need to do to reconcile our replica with the peer replica it was compared to.
29	 */
30	public class ContainerDiffReport {
31	  private final List<ContainerProtos.BlockMerkleTree> missingBlocks;
32	  private final Map<Long, List<ContainerProtos.ChunkMerkleTree>> missingChunks;
33	  private final Map<Long, List<ContainerProtos.ChunkMerkleTree>> corruptChunks;
34	  private final List<DeletedBlock> divergedDeletedBlocks;
35	  private final long containerID;
36	
37	  public ContainerDiffReport(long containerID) {
38	    this.missingBlocks = new ArrayList<>();
39	    this.missingChunks = new HashMap<>();
40	    this.corruptChunks = new HashMap<>();
41	    this.divergedDeletedBlocks = new ArrayList<>();
42	    this.containerID = containerID;
43	  }
44	
45	  public long getContainerID() {
46	    return containerID;
47	  }
48	
49	  /**
50	   * @param missingBlockMerkleTree The block merkle tree of the block to report as missing.
51	   */
52	  public void addMissingBlock(ContainerProtos.BlockMerkleTree missingBlockMerkleTree) {
53	    this.missingBlocks.add(missingBlockMerkleTree);
54	  }
55	
56	  /**
57	   * @param blockId The ID of the block with missing chunks identified.
58	   * @param missingChunkMerkleTree The chunk within this block to report as missing.
59	   */
60	  public void addMissingChunk(long blockId, ContainerProtos.ChunkMerkleTree missingChunkMerkleTree) {
61	    this.missingChunks.computeIfAbsent(blockId, any -> new ArrayList<>()).add(missingChunkMerkleTree);
62	  }
63	
64	  /**
65	   * @param blockId The ID of the block with missing chunks identified.
66	   * @param corruptChunk The chunk within this block to report as corrupt.
67	   */
68	  public void addCorruptChunk(long blockId, ContainerProtos.ChunkMerkleTree corruptChunk) {
69	    this.corruptChunks.computeIfAbsent(blockId, any -> new ArrayList<>()).add(corruptChunk);
70	  }
71	
72	  public void addDivergedDeletedBlock(ContainerProtos.BlockMerkleTree blockMerkleTree) {
73	    this.divergedDeletedBlocks.add(new DeletedBlock(blockMerkleTree.getBlockID(), blockMerkleTree.getDataChecksum()));
74	  }
75	
76	  /**
77	   * @return A list of BlockMerkleTree objects that were reported as missing.
78	   */
79	  public List<ContainerProtos.BlockMerkleTree> getMissingBlocks() {
80	    return missingBlocks;
81	  }
82	
83	  /**
84	   * @return A map of block IDs to lists of missing ChunkMerkleTree objects within those blocks.
85	   */
86	  public Map<Long, List<ContainerProtos.ChunkMerkleTree>> getMissingChunks() {
87	    return missingChunks;
88	  }
89	
90	  /**
91	   * @return A map of block IDs to lists of corrupt ChunkMerkleTree objects within those blocks.
92	   */
93	  public Map<Long, List<ContainerProtos.ChunkMerkleTree>> getCorruptChunks() {
94	    return corruptChunks;
95	  }
96	
97	  public List<DeletedBlock> getDivergedDeletedBlocks() {
98	    return divergedDeletedBlocks;
99	  }
100	
101	  /**
102	   * If needRepair is true, It means current replica needs blocks/chunks from the peer to repair
103	   * its container replica. The peer replica still may have corruption, which it will fix when
104	   * it reconciles with other peers.
105	   */
106	  public boolean needsRepair() {
107	    return !missingBlocks.isEmpty() || !missingChunks.isEmpty() || !corruptChunks.isEmpty() ||
108	        !divergedDeletedBlocks.isEmpty();
109	  }
110	
111	  public long getNumCorruptChunks() {
112	    return corruptChunks.values().stream().mapToInt(List::size).sum();
113	  }
114	
115	  public long getNumMissingChunks() {
116	    return missingChunks.values().stream().mapToInt(List::size).sum();
117	  }
118	
119	  public long getNumMissingBlocks() {
120	    return missingBlocks.size();
121	  }
122	
123	  public long getNumdivergedDeletedBlocks() {
124	    return divergedDeletedBlocks.size();
125	  }
126	
127	  @Override
128	  public String toString() {
129	    return "Diff report for container " + containerID + ":" +
130	        " Missing Blocks: " + getNumMissingBlocks() +
131	        " Missing Chunks: " + getNumMissingChunks() + " chunks from " + missingChunks.size() + " blocks" +
132	        " Corrupt Chunks: " + getNumCorruptChunks() + " chunks from " + corruptChunks.size() + " blocks" +
133	        " Diverged Deleted Blocks: " + getNumdivergedDeletedBlocks();
134	  }
135	
136	  /**
137	   * Represents a block that has been deleted in a peer whose metadata we need to add to our container replica's
138	   * merkle tree.
139	   */
140	  public static class DeletedBlock {
141	    private final long blockID;
142	    private final long dataChecksum;
143	
144	    public DeletedBlock(long blockID, long dataChecksum) {
145	      this.blockID = blockID;
146	      this.dataChecksum = dataChecksum;
147	    }
148	
149	    public long getBlockID() {
150	      return blockID;
151	    }
152	
153	    public long getDataChecksum() {
154	      return dataChecksum;
155	    }
156	  }
157	}
